const e={title:"ਅਸੀਂ ਕੂਕੀਜ਼ ਵਰਤਦੇ ਹਾਂ",description:"ਅਸੀਂ ਆਪਣੀਆਂ ਸੇਵਾਵਾਂ ਚਲਾਉਣ, ਤੁਹਾਨੂੰ ਸਾਈਨ ਇਨ ਰੱਖਣ ਅਤੇ ਤੁਹਾਡੇ ਅਨੁਭਵ ਨੂੰ ਬਿਹਤਰ ਬਣਾਉਣ ਲਈ ਕੂਕੀਜ਼ ਵਰਤਦੇ ਹਾਂ। ਤੁਸੀਂ ਹੇਠਾਂ ਆਪਣੀਆਂ ਤਰਜੀਹਾਂ ਪ੍ਰਬੰਧਿਤ ਕਰ ਸਕਦੇ ਹੋ।",accept_all:"ਸਭ ਸਵੀਕਾਰ ਕਰੋ",reject_all:"ਸਭ ਰੱਦ ਕਰੋ",manage:"ਤਰਜੀਹਾਂ ਪ੍ਰਬੰਧਿਤ ਕਰੋ",privacy_link:"ਗੋਪਨੀਯਤਾ ਨੀਤੀ"},a={title:"ਕੂਕੀ ਤਰਜੀਹਾਂ",save:"ਤਰਜੀਹਾਂ ਸੁਰੱਖਿਅਤ ਕਰੋ",strictly_necessary:{label:"ਸਖ਼ਤੀ ਨਾਲ ਜ਼ਰੂਰੀ",description:"ਸਾਈਟ ਦੇ ਕੰਮ ਕਰਨ ਲਈ ਲੋੜੀਂਦਾ। ਅਯੋਗ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ।"},functional:{label:"ਕਾਰਜਸ਼ੀਲ",description:"ਤੁਹਾਡੀਆਂ ਸੈਟਿੰਗਾਂ ਯਾਦ ਰੱਖਣ ਵਰਗੀਆਂ ਵਧੀਆਂ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਨੂੰ ਸਮਰੱਥ ਬਣਾਉਂਦਾ ਹੈ।"},analytics:{label:"ਵਿਸ਼ਲੇਸ਼ਣਾਤਮਕ",description:"ਸਾਨੂੰ ਸਮਝਣ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ ਕਿ ਤੁਸੀਂ ਸਾਈਟ ਦੀ ਵਰਤੋਂ ਕਿਵੇਂ ਕਰਦੇ ਹੋ।"},marketing:{label:"ਮਾਰਕੀਟਿੰਗ",description:"ਸੰਬੰਧਿਤ ਇਸ਼ਤਿਹਾਰ ਦਿਖਾਉਣ ਅਤੇ ਮੁਹਿੰਮਾਂ ਨੂੰ ਟਰੈਕ ਕਰਨ ਲਈ ਵਰਤਿਆ ਜਾਂਦਾ ਹੈ।"}},n={banner:e,preferences:a};export{e as banner,n as default,a as preferences};
